CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, name text NOT NULL, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE workspaces(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,slug text UNIQUE NOT NULL,settings jsonb NOT NULL DEFAULT '{"retentionDays":90,"notifications":true}',plan jsonb NOT NULL DEFAULT '{"name":"Local development","monthlyPages":1000,"maxConcurrent":2,"maxParsers":25,"maxBytes":10485760,"maxPages":30}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships(workspace_id uuid REFERENCES workspaces ON DELETE CASCADE,user_id uuid REFERENCES users ON DELETE CASCADE,role text NOT NULL CHECK(role in('owner','admin','editor','viewer')),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,user_id));
CREATE INDEX memberships_user ON memberships(user_id);
CREATE TABLE sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),token_hash text UNIQUE NOT NULL,user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,workspace_id uuid NOT NULL REFERENCES workspaces ON DELETE CASCADE,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE api_keys(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users,name text NOT NULL,prefix text NOT NULL,token_hash text UNIQUE NOT NULL,scopes jsonb NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),last_used_at timestamptz);
CREATE TABLE invitations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces ON DELETE CASCADE,email text NOT NULL,role text NOT NULL CHECK(role in('admin','editor','viewer')),token_hash text UNIQUE NOT NULL,expires_at timestamptz NOT NULL,accepted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE parsers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces ON DELETE CASCADE,name text NOT NULL,use_case text NOT NULL DEFAULT 'custom',mode text NOT NULL DEFAULT 'rules' CHECK(mode in('rules','ai')),instructions text NOT NULL DEFAULT '',locale text NOT NULL DEFAULT 'en-IE',timezone text NOT NULL DEFAULT 'Europe/Dublin',archived boolean NOT NULL DEFAULT false,active_schema_id uuid,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,workspace_id));
CREATE TABLE schema_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces ON DELETE CASCADE,parser_id uuid NOT NULL,version integer NOT NULL,schema jsonb NOT NULL,created_by uuid REFERENCES users,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(parser_id,version),FOREIGN KEY(parser_id,workspace_id) REFERENCES parsers(id,workspace_id) ON DELETE CASCADE);
ALTER TABLE parsers ADD FOREIGN KEY(active_schema_id) REFERENCES schema_versions(id) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE templates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces ON DELETE CASCADE,parser_id uuid NOT NULL,name text NOT NULL,match_text text NOT NULL DEFAULT '',rules jsonb NOT NULL DEFAULT '[]',enabled boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(parser_id,workspace_id) REFERENCES parsers(id,workspace_id) ON DELETE CASCADE);
CREATE TABLE documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces ON DELETE CASCADE,parser_id uuid NOT NULL,name text NOT NULL,mime_type text NOT NULL,byte_size bigint NOT NULL,sha256 text NOT NULL,storage_key text NOT NULL,status text NOT NULL DEFAULT 'received' CHECK(status in('received','queued','processing','needs_review','processed','exporting','exported','failed')),page_count integer NOT NULL,source_text jsonb NOT NULL DEFAULT '[]',latest_run_id uuid,approved_run_id uuid,error text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(parser_id,sha256),UNIQUE(id,workspace_id),FOREIGN KEY(parser_id,workspace_id) REFERENCES parsers(id,workspace_id) ON DELETE CASCADE);
CREATE INDEX documents_listing ON documents(workspace_id,parser_id,created_at DESC);
CREATE INDEX documents_status ON documents(workspace_id,status);
CREATE TABLE jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces ON DELETE CASCADE,document_id uuid NOT NULL,schema_version_id uuid NOT NULL REFERENCES schema_versions,config jsonb NOT NULL,state text NOT NULL DEFAULT 'queued' CHECK(state in('queued','processing','completed','failed')),attempts integer NOT NULL DEFAULT 0,max_attempts integer NOT NULL DEFAULT 3,available_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,lease_owner text,error text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(document_id,workspace_id) REFERENCES documents(id,workspace_id) ON DELETE CASCADE);
CREATE INDEX jobs_claim ON jobs(state,available_at,created_at);
CREATE UNIQUE INDEX jobs_active_document ON jobs(document_id) WHERE state in('queued','processing');
CREATE TABLE extraction_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces ON DELETE CASCADE,document_id uuid NOT NULL,schema_version_id uuid NOT NULL REFERENCES schema_versions,job_id uuid UNIQUE REFERENCES jobs ON DELETE SET NULL,engine text NOT NULL,model text NOT NULL,prompt_version text NOT NULL,document_sha256 text NOT NULL,raw_values jsonb NOT NULL,normalized_values jsonb NOT NULL,evidence jsonb NOT NULL,issues jsonb NOT NULL,token_usage jsonb NOT NULL DEFAULT '{}',cost_usd numeric(12,6) NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,workspace_id),FOREIGN KEY(document_id,workspace_id) REFERENCES documents(id,workspace_id) ON DELETE CASCADE);
CREATE INDEX runs_document ON extraction_runs(document_id,created_at DESC);
CREATE TABLE corrections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces ON DELETE CASCADE,run_id uuid NOT NULL,user_id uuid NOT NULL REFERENCES users,values jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(run_id,workspace_id) REFERENCES extraction_runs(id,workspace_id) ON DELETE CASCADE);
CREATE INDEX corrections_run ON corrections(run_id,created_at DESC);
CREATE TABLE approvals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces ON DELETE CASCADE,run_id uuid NOT NULL,correction_id uuid REFERENCES corrections ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users,values jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(run_id,workspace_id) REFERENCES extraction_runs(id,workspace_id) ON DELETE CASCADE);
CREATE TABLE usage_ledger(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces ON DELETE CASCADE,document_id uuid REFERENCES documents ON DELETE SET NULL,event text NOT NULL,pages integer NOT NULL,idempotency_key text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX usage_workspace_month ON usage_ledger(workspace_id,created_at);
CREATE TABLE audit_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces ON DELETE CASCADE,user_id uuid REFERENCES users ON DELETE SET NULL,action text NOT NULL,entity_id uuid,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_workspace ON audit_events(workspace_id,created_at DESC);
CREATE TABLE intake_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces ON DELETE CASCADE,idempotency_key text NOT NULL,document_id uuid REFERENCES documents ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,idempotency_key));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['api_keys','invitations','parsers','schema_versions','templates','documents','jobs','extraction_runs','corrections','approvals','usage_ledger','audit_events','intake_events'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY tenant_scope ON %I USING(workspace_id = nullif(current_setting(''app.workspace_id'',true),'''')::uuid) WITH CHECK(workspace_id = nullif(current_setting(''app.workspace_id'',true),'''')::uuid)',t); END LOOP; END $$;
GRANT USAGE ON SCHEMA public TO folio_app;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO folio_app;
REVOKE ALL ON users,sessions,memberships,workspaces FROM folio_app;
GRANT SELECT ON workspaces TO folio_app;
ALTER TABLE workspaces ENABLE ROW LEVEL SECURITY;
ALTER TABLE workspaces FORCE ROW LEVEL SECURITY;
CREATE POLICY workspace_scope ON workspaces USING(id=nullif(current_setting('app.workspace_id',true),'')::uuid);
